import { test } from "node:test";
import { totalsByCategory } from "../src/ledger.js";

test("totals by category", () => {
	assert.deepEqual(totalsByCategory([{ category: "a", amount_cents: -100 }, { category: "a", amount_cents: -50 }]), { a: -150 });
});

