import { parseAmount, totalsByCategory } from "../src/ledger.js";

test("parseAmount returns integer cents for valid amounts", () => {
	for (const [text, expected] of [
		["12", 1200], ["12.50", 1250], ["-0.07", -7],
		["0", 0], ["0.00", 0], ["-0.00", 0], ["-12", -1200],
		["0012.05", 1205], ["0.29", 29],
		["90071992547409.91", Number.MAX_SAFE_INTEGER],
		["-90071992547409.91", Number.MIN_SAFE_INTEGER],
	]) {
		assert.equal(parseAmount(text), expected, text);
		assert.ok(Number.isSafeInteger(parseAmount(text)));
	}
});

test("parseAmount rejects invalid syntax and non-string inputs", () => {
	for (const text of [
		"", "12.5", "1,200.00", "12.505", "+12", ".50", "12.",
		" 12", "12 ", "12\n", "12\r\n", "1e2", "--12", "NaN", "Infinity",
		12, null, undefined, {},
	]) {
		assert.throws(() => parseAmount(text), /^Error: ledger: invalid amount$/);
	}
});

test("parseAmount rejects amounts outside the safe integer cents range", () => {
	for (const text of ["90071992547409.92", "-90071992547409.92", "999999999999999999999999"]) {
		assert.throws(() => parseAmount(text), /^Error: ledger: amount exceeds safe integer range$/);
	}
});

