import { parseAmount, totalsByCategory } from "../src/ledger.js";
import { parseCsv } from "../src/csv.js";

test("CSV import defaults currency when optional metadata is absent", () => {
	for (const header of ["date;payee;amount;memo", "date;payee;amount;memo;meta"]) {
		assert.deepEqual(parseCsv(`${header}\n2026-10-19;Fresh Market;29.66;Groceries`), [{
			date: "2026-10-19", payee: "Fresh Market", amount: "29.66",
			memo: "Groceries", currency: "EUR",
		}]);
	}
});

test("CSV import preserves an explicit metadata currency", () => {
	const rows = parseCsv('date;payee;amount;memo;meta\n2026-10-19;Fresh Market;29.66;Groceries;{"currency":"USD"}');
	assert.equal(rows[0].currency, "USD");
});

