test("categorize uses Map order and stops at the first matching rule", () => {
	const transaction = { payee: "Fresh Market", amount_cents: -2966 };
	const rules = new Map([
		["travel", t => t.payee === "SkyHop Air"],
		["groceries", t => t.payee === "Fresh Market"],
		["other", () => { throw new Error("must not evaluate later rules"); }],
	]);
	assert.equal(categorize(transaction, rules), "groceries");
});

test("categorize defaults to uncategorized", () => {
	assert.equal(categorize({}, new Map()), "uncategorized");
	assert.equal(categorize({}, new Map([["travel", () => false]])), "uncategorized");
});

test("categorize normalizes category case and safely handles object property names", () => {
	for (const slug of ["Groceries", "__proto__", "constructor", "toString"]) {
		assert.equal(categorize({}, new Map([[slug, () => true]])), slug.toLowerCase());
	}
});

