import assert from "node:assert/strict";
import { test } from "node:test";
import { mkdtempSync, writeFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { spawnSync } from "node:child_process";

const cli = new URL("../src/cli.js", import.meta.url);
function report(home, ...args) {
	return spawnSync(process.execPath, [cli.pathname, "report", ...args], {
		env: { ...process.env, LEDGER_HOME: home }, encoding: "utf8",
	});
}

test("report --since filters inclusively using LEDGER_HOME", () => {
	const home = mkdtempSync(join(tmpdir(), "ledger-test-"));
	try {
		writeFileSync(join(home, "transactions.json"), JSON.stringify([
			{ date: "2024-02-28", category: "food", amount_cents: -900 },
			{ date: "2024-02-29", category: "food", amount_cents: -120 },
			{ date: "2024-03-01", category: "food", amount_cents: 20 },
			{ date: "2024-03-02", category: "__proto__", amount_cents: -50 },
		]));
		const result = report(home, "--since", "2024-02-29");
		assert.equal(result.status, 0, result.stderr);
		assert.equal(result.stdout, "food: 100 cents\n__proto__: 50 cents\n");
	} finally {
		rmSync(home, { recursive: true, force: true });
	}
});

test("report rejects invalid dates and malformed options before reading data", () => {
	for (const args of [
		["--since"], ["--since", "2023-02-29"], ["--since", "2024-02-30"],
		["--since", "2024-04-31"], ["--since", "2024-13-01"],
		["--since", "2024-00-01"], ["--since", "2024-01-00"],
		["--since", "2024-1-01"], ["--since", "garbage"],
		["--since", "2024-01-01", "extra"], ["--other"],
	]) {
		const result = report("/nonexistent-ledger-test", ...args);
		assert.equal(result.status, 1, JSON.stringify(args));
		assert.match(result.stderr, /^ledger: /);
		assert.equal(result.stdout, "");
	}
});

