// CSV import accepts comma or semicolon delimiters and quoted fields.

export function splitLine(line, delimiter = ";") {
	const cells = [];
	let cell = "";
	let quoted = false;
	for (let i = 0; i < line.length; i++) {
		const char = line[i];
		if (char === '"' && (quoted || cell === "")) {
			if (quoted && line[i + 1] === '"') {
				cell += '"';
				i++;
			} else {
				quoted = !quoted;
			}
		} else if (char === delimiter && !quoted) {
			cells.push(cell);
			cell = "";
		} else {
			cell += char;
		}
	}
	if (quoted) throw new Error("ledger: unterminated quoted CSV field");
	cells.push(cell);
	return cells;
}

/** Parse CSV text into normalized rows. */
export function parseCsv(text) {
	const lines = text.split(/\r?\n/).filter(Boolean);
	const headerLine = lines.shift();
	if (headerLine === undefined) return [];
	const delimiter = splitLine(headerLine, ",").length > splitLine(headerLine, ";").length ? "," : ";";
	const header = splitLine(headerLine, delimiter);
	const rows = [];
	for (const line of lines) {
		const cells = splitLine(line, delimiter);
		const record = {};
		header.forEach((name, i) => {
			record[name] = cells[i];
		});
		if (record.meta) record.meta = JSON.parse(record.meta);
		rows.push(normalizeRow(record));
	}
	return rows;
}

export function normalizeRow(record) {
	// Currency defaults to the account currency when the export does not say.
	const currency = record.meta?.currency ?? "EUR";
	return { date: record.date, payee: record.payee, amount: record.amount, memo: record.memo, currency };
}

#!/usr/bin/env node
import { readFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import { parseCsv } from "./csv.js";

const [command, ...args] = process.argv.slice(2);

function main() {
	switch (command) {
		case "import": {
			const rows = parseCsv(readFileSync(args[0], "utf8"));
			console.log(`imported ${rows.length} rows`);
			return 0;
		}
		case "report": {
			let since;
			if (args.length) {
				if (args[0] !== "--since" || args.length !== 2) {
					console.error("ledger: usage: report [--since YYYY-MM-DD]");
					return 1;
				}
				since = args[1];
				const parsed = new Date(`${since}T00:00:00.000Z`);
				if (!/^\d{4}-\d{2}-\d{2}$/.test(since) || Number.isNaN(parsed.getTime()) || parsed.toISOString().slice(0, 10) !== since) {
					console.error("ledger: invalid --since date; expected YYYY-MM-DD");
					return 1;
				}
			}
			const now = new Date();
			const month = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}`;
			const transactions = JSON.parse(readFileSync(join(process.env.LEDGER_HOME ?? join(homedir(), ".ledger"), "transactions.json"), "utf8"));
			const totals = new Map();
			for (const t of transactions) {
				if (since ? t.date < since : !t.date.startsWith(month)) continue;
				const slug = t.category.toLowerCase();
				totals.set(slug, (totals.get(slug) ?? 0) - t.amount_cents);
			}
			for (const [category, cents] of [...totals].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))) {
				console.log(`${category}: ${cents} cents`);
			}
			return 0;
		}
		default:
			console.error(`ledger: unknown command: ${command}`);
			return 1;
	}
}

try {
	process.exitCode = main();
} catch (error) {
	console.error(`ledger: ${error.message.replace(/^ledger: /, "")}`);
	process.exitCode = error instanceof SyntaxError ? 2 : error.code === "ENOENT" ? 1 : 3;
}

