test("report rejects corrupt transaction data and sums cents exactly", () => {
	const home = mkdtempSync(join(tmpdir(), "ledger-test-"));
	const valid = { date: "2024-03-01", category: "food", amount_cents: -100 };
	try {
		for (const data of [{}, [null], [{ ...valid, date: "2024-02-30" }],
			[{ ...valid, category: null }], [{ ...valid, amount_cents: "100" }],
			[{ ...valid, amount_cents: 1.5 }], [{ ...valid, amount_cents: Number.MAX_SAFE_INTEGER + 1 }]]) {
			writeFileSync(join(home, "transactions.json"), JSON.stringify(data));
			const result = report(home, "--since", "2024-01-01");
			assert.equal(result.status, 2);
			assert.match(result.stderr, /^ledger: /);
			assert.equal(result.stdout, "");
		}
		writeFileSync(join(home, "transactions.json"), JSON.stringify([
			{ ...valid, amount_cents: -Number.MAX_SAFE_INTEGER },
			{ ...valid, amount_cents: -2 },
		]));
		const result = report(home, "--since", "2024-01-01");
		assert.equal(result.status, 0, result.stderr);
		assert.equal(result.stdout, "food: 9007199254740993 cents\n");
	} finally {
		rmSync(home, { recursive: true, force: true });
	}
});

