test("balance sums all accounts and formats integer cents in account-name order", () => {
	const home = mkdtempSync(join(tmpdir(), "ledger-test-"));
	const run = (...args) => spawnSync(process.execPath, [cli.pathname, "balance", ...args], {
		env: { ...process.env, LEDGER_HOME: home }, encoding: "utf8",
	});
	try {
		writeFileSync(join(home, "transactions.json"), JSON.stringify([
			{ account: "Savings", amount_cents: 120005 },
			{ account: "Checking", amount_cents: 100 },
			{ account: "Checking", amount_cents: -107 },
			{ account: "Credit Card", amount_cents: -12345 },
			{ account: "__proto__", amount_cents: 0 },
			{ account: "checking", amount_cents: 1 },
			{ account: "Large", amount_cents: Number.MAX_SAFE_INTEGER },
			{ account: "Large", amount_cents: 2 },
		]));
		const result = run();
		assert.equal(result.status, 0, result.stderr);
		assert.equal(result.stdout, "Checking: -0.07\nCredit Card: -123.45\nLarge: 90071992547409.93\nSavings: 1200.05\n__proto__: 0.00\nchecking: 0.01\n");
		assert.equal(run("extra").status, 1);
		assert.match(run("extra").stderr, /^ledger: /);
		writeFileSync(join(home, "transactions.json"), "[]");
		assert.equal(run().stdout, "");
		for (const data of [{}, [null], [{ account: "Checking", amount_cents: "100" }], [{ amount_cents: 100 }]]) {
			writeFileSync(join(home, "transactions.json"), JSON.stringify(data));
			const invalid = run();
			assert.equal(invalid.status, 2);
			assert.match(invalid.stderr, /^ledger: /);
			assert.equal(invalid.stdout, "");
		}
	} finally {
		rmSync(home, { recursive: true, force: true });
	}
});

